(function(global){
function parse(text,existing=[]){if(text.length>200000)throw Error('Use a file smaller than 200 KB.');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Unclosed quotation mark. Please check your CSV file.');row.push(cell);rows.push(row);const nonempty=rows.filter(r=>r.some(c=>c.trim()));if(nonempty.length>501)throw Error('Upload at most 500 employees at a time.');const headers=nonempty[0]?.map(c=>c.replace(/^\uFEFF/,'').trim().toLowerCase())||[];let column=headers.findIndex(c=>['name','employee name','full name','employee_name'].includes(c));const hasHeader=column>=0;if(!hasHeader)column=0;if(!hasHeader&&nonempty.some(r=>r.length>1))throw Error('For multiple columns include an Employee Name header.');const seen=new Set(existing.map(n=>n.trim().toLocaleLowerCase()));return nonempty.slice(hasHeader?1:0).map((r,i)=>{const name=(r[column]||'').replace(/^\uFEFF/,'').trim().replace(/\s+/g,' ');let issue='';const key=name.toLocaleLowerCase();if(!name)issue='Name required';else if(name.length>120||/[<>\x00-\x1f]/.test(name)||/^[=+@]/.test(name))issue='Invalid name';else if(seen.has(key))issue='Duplicate name — review separately';if(!issue)seen.add(key);return {name,row:i+(hasHeader?2:1),issue}})}
if(typeof module!=='undefined')module.exports={parse};if(!global.document)return;global.Onboarding={parse};
let preview=[],fileName='',reading=0;
const permitted=()=>role==='HR officer'&&!signedOut;
global.onboardingSection=function(){if(!permitted())return '';const records=state.onboarding||[];return card('Employee onboarding',`<div class="onboard-intro"><div><span class="eyebrow">HR INTAKE</span><h3>Start with your new joiners.</h3><p>Upload employee names, review the list, and create an onboarding record for each person.</p></div>${btn('Upload employee list',"onboardingUpload()",'primary')}</div><div class="onboard-note">CSV or TXT · One name per line, or a CSV with an Employee Name column · Up to 500 names. Records are saved in this browser. Use sample names in this demo.</div><div class="toolbar">${btn('Download CSV template',"download('onboarding-template.csv','Employee Name\\nAditi Roy\\nRohan Sen\\n')")}</div>${records.length?`<div class="tablewrap"><table><thead><tr><th>EMPLOYEE</th><th>CASE</th><th>STATUS</th><th>STARTED</th><th></th></tr></thead><tbody>${records.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.id)}</td><td>${badge('Initiated')}</td><td>${esc(r.started)}</td><td>${btn('Open →',`onboardingDetail('${r.id}')`,'link')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No onboarding records yet. Upload a list to begin.</div>'}<div class="cardfoot">${records.length} onboarding records · Detailed stages will be added as the process is defined.</div>`)};
global.onboardingUpload=function(){if(!permitted())return;preview=[];fileName='';reading++;modal('Upload employee list',`<p>Start onboarding by uploading a CSV or TXT list of employee names.</p><label class="field">Employee list<input id="onboardFile" type="file" accept=".csv,.txt,text/csv,text/plain" onchange="onboardingRead(this.files[0])"></label><p class="sub">Maximum 200 KB and 500 employees. Excel files: save as CSV first.</p><div id="onboardPreview" aria-live="polite"></div>`,btn('Cancel',"$('#dialog').close()")+`<button class="primary" id="onboardStart" onclick="onboardingStart()" disabled>Start onboarding</button>`)};
global.onboardingRead=async function(file){if(!permitted())return;const token=++reading;preview=[];$('#onboardStart').disabled=true;if(!file)return;fileName=file.name;try{if(!/\.(csv|txt)$/i.test(file.name))throw Error('Choose a CSV or TXT file.');if(file.size>200000)throw Error('Use a file smaller than 200 KB.');const content=await file.text();if(token!==reading||!permitted()||!$('#onboardPreview'))return;preview=parse(content,(state.onboarding||[]).map(r=>r.name));const valid=preview.filter(r=>!r.issue);$('#onboardPreview').innerHTML=`<h3>Review ${esc(fileName)}</h3><p>${valid.length} ready · ${preview.length-valid.length} excluded</p><p class="sub">Duplicates and invalid rows will be skipped. Namesakes can be reviewed separately when employee identifiers are added.</p><div class="tablewrap" style="max-height:280px;overflow:auto"><table><thead><tr><th>ROW</th><th>EMPLOYEE NAME</th><th>RESULT</th></tr></thead><tbody>${preview.map(r=>`<tr><td>${r.row}</td><td>${esc(r.name)}</td><td>${r.issue?esc(r.issue):'Ready'}</td></tr>`).join('')}</tbody></table></div>`;$('#onboardStart').disabled=!valid.length;$('#onboardStart').textContent='Start onboarding ('+valid.length+')'}catch(e){if(token===reading&&$('#onboardPreview'))$('#onboardPreview').textContent=e.message}};
global.onboardingStart=function(){if(!permitted()||!preview.length)return;const existing=new Set((state.onboarding||[]).map(r=>r.name.toLocaleLowerCase()));const ready=preview.filter(r=>!r.issue&&!existing.has(r.name.toLocaleLowerCase()));if(!ready.length)return;const previous=state.onboarding||[];const now=new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'});const batch=crypto.randomUUID();const records=ready.map(r=>({id:'ONB-'+crypto.randomUUID(),batch,name:r.name,started:now,by:person().name,status:'Initiated',history:[{date:now,action:'Onboarding initiated from employee list'}]}));state.onboarding=[...records,...previous];try{audit('Onboarding batch initiated: '+records.length+' employees');save()}catch{state.onboarding=previous;state.audit.pop();toast('Unable to save. Browser storage may be full.');return}preview=[];$('#dialog').close();render();toast(records.length+' onboarding records initiated.')};
global.onboardingDetail=function(id){if(!permitted())return;const r=(state.onboarding||[]).find(r=>r.id===id);if(!r)return;modal('Employee onboarding',`<h3>${esc(r.name)}</h3>${profilePairs([['Case ID',r.id],['Status','Initiated'],['Started',r.started],['Initiated by',r.by]])}<div class="callout">Employee list received and onboarding record created. Subsequent stages are awaiting process definition.</div><h3>Activity history</h3>${r.history.map(e=>`<p>${esc(e.date)} · ${esc(e.action)}</p>`).join('')}`,btn('Close',"$('#dialog').close()"))};
})(typeof window!=='undefined'?window:globalThis);
